    /// <summary>
    /// Header contract
    /// </summary>
    /// <param name = "_headerContract">Set header contract</param>
    /// <returns>Get header contract</returns>
    [DataMember("Header")]
    public METInventTransferOrderReceiveHeaderContract parmHeaderContract(METInventTransferOrderReceiveHeaderContract _headerContract = headerContract)
    {
        if (!prmIsDefault(_headerContract))
        {
            headerContract = _headerContract;
        }

        return headerContract;
    }

    /// <summary>
